import React from 'react';
import MeshSphere from '../components/MeshSphere';
import { useMoods, useThoughts } from '../hooks/useStorage';

const TRAP_SHORT = {
  'Katastrofiering':'KATASTR.','Tankeläsning':'TANKELÄS.','Svartvitt tänkande':'SVART/VIT',
  'Övergeneralisering':'ÖVERGENER.','Känslomässigt resonerande':'KÄNSLO.','Personalisering':'PERSONAL.',
  'Filtrerande':'FILTR.','Bör-tänkande':'BÖR-TÄNK.'
};
const MOOD_COLORS = {1:'#e05050',2:'#d07840',3:'#c8b040',4:'#50a870',5:'#5090d0'};
const MOOD_LABELS = {1:'Väldigt dåligt',2:'Dåligt',3:'Okej',4:'Bra',5:'Väldigt bra'};

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();
  const isEmpty = moods.length===0 && thoughts.length===0;
  const maxTrap = Math.max(...Object.values(trapCounts), 1);

  if (isEmpty) return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:80, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 20px' }}>
      <MeshSphere size={220} speed={0.3} distort={0.5} />
      <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.24em', textTransform:'uppercase', color:'rgba(242,240,235,0.25)', marginTop:24, marginBottom:12 }}>Historik · Ingen data</div>
      <h2 style={{ fontSize:28, fontWeight:900, letterSpacing:'-0.04em', textTransform:'uppercase', color:'#f2f0eb', marginBottom:24 }}>Tom historik</h2>
      <div style={{ display:'flex', gap:8 }}>
        <button onClick={()=>setPage('home')} style={{ padding:'12px 20px', border:'none', borderRadius:4, background:'#f2f0eb', color:'#0c0c0e', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase', fontWeight:700 }}>Analysera</button>
        <button onClick={()=>setPage('checkin')} style={{ padding:'12px 20px', border:'1px solid rgba(255,255,255,0.1)', borderRadius:4, color:'rgba(242,240,235,0.5)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase' }}>Check-in</button>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:80, position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px)', backgroundSize:'48px 48px', pointerEvents:'none' }} />

      <div style={{ padding:'24px 20px', position:'relative', zIndex:1 }}>
        <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.24em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:8 }}>Din historik</div>
        <h1 style={{ fontSize:'clamp(36px,9vw,56px)', fontWeight:900, letterSpacing:'-0.06em', lineHeight:0.86, textTransform:'uppercase', color:'#f2f0eb', marginBottom:28 }}>
          DATA<br/><span style={{ color:'rgba(242,240,235,0.18)' }}>LOGG</span>
        </h1>

        {/* Stats — three cells in a grid */}
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:1, marginBottom:1, background:'rgba(255,255,255,0.06)' }}>
          {[
            { val:streak, label:'Streak', suffix:'dgr' },
            { val:thoughts.length, label:'Analyser', suffix:'st' },
            { val:avgMood>0?avgMood:'—', label:'Snitt', suffix:'' },
          ].map(({val,label,suffix})=>(
            <div key={label} style={{ background:'#0c0c0e', padding:'16px 12px', textAlign:'center' }}>
              <div style={{ fontSize:26, fontWeight:900, letterSpacing:'-0.04em', color:'#f2f0eb', lineHeight:1 }}>{val}<span style={{ fontSize:12, color:'rgba(242,240,235,0.3)', fontWeight:400, marginLeft:2 }}>{suffix}</span></div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginTop:4 }}>{label}</div>
            </div>
          ))}
        </div>

        {/* Mood chart */}
        {moods.length > 0 && (
          <div style={{ marginBottom:1, border:'1px solid rgba(255,255,255,0.06)', padding:'16px', background:'rgba(255,255,255,0.02)' }}>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:16 }}>Humör · Trend</div>
            <div style={{ display:'flex', alignItems:'flex-end', gap:3, height:64 }}>
              {[...moods].reverse().map((m,i)=>(
                <div key={i} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:2, height:'100%', justifyContent:'flex-end' }}>
                  <div style={{ width:'100%', background:MOOD_COLORS[m.score], height:`${(m.score/5)*100}%`, minHeight:3, borderRadius:'1px 1px 0 0', boxShadow:`0 0 8px ${MOOD_COLORS[m.score]}55` }} title={MOOD_LABELS[m.score]} />
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:6, color:'rgba(242,240,235,0.2)', whiteSpace:'nowrap', transform:'rotate(-45deg)', transformOrigin:'top center', marginTop:4, display:'block' }}>
                    {new Date(m.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Trap frequency — unique visualization */}
        {Object.keys(trapCounts).length > 0 && (
          <div style={{ marginBottom:1, border:'1px solid rgba(255,255,255,0.06)', padding:'16px', background:'rgba(255,255,255,0.02)' }}>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:14 }}>Tankefällor · Frekvens</div>
            {Object.entries(trapCounts).sort((a,b)=>b[1]-a[1]).map(([label, count]) => (
              <div key={label} style={{ display:'flex', alignItems:'center', gap:10, marginBottom:10 }}>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(242,240,235,0.4)', width:72, flexShrink:0, letterSpacing:'0.06em' }}>{TRAP_SHORT[label]||label.slice(0,8).toUpperCase()}</div>
                <div style={{ flex:1, height:2, background:'rgba(255,255,255,0.06)' }}>
                  <div style={{ height:'100%', background:'rgba(242,240,235,0.5)', width:`${(count/maxTrap)*100}%`, boxShadow:'0 0 6px rgba(242,240,235,0.2)', transition:'width .8s cubic-bezier(0.16,1,0.3,1)' }} />
                </div>
                <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(242,240,235,0.3)', width:14, textAlign:'right' }}>{count}</span>
              </div>
            ))}
          </div>
        )}

        {/* Thought log */}
        {thoughts.length > 0 && (
          <>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', margin:'20px 0 8px' }}>Log · Analyser</div>
            {thoughts.map((th, i) => (
              <div key={th.id} style={{ border:'1px solid rgba(255,255,255,0.06)', marginBottom:4, background:'rgba(255,255,255,0.02)', position:'relative', overflow:'hidden' }}>
                {/* Left accent bar */}
                <div style={{ position:'absolute', top:0, left:0, bottom:0, width:2, background:'rgba(242,240,235,0.1)' }} />
                <div style={{ padding:'12px 14px 12px 18px' }}>
                  <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:6 }}>
                    <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.12em', textTransform:'uppercase', color:'rgba(242,240,235,0.45)' }}>{th.trap_icon||'▸'} {th.trap_label}</span>
                    <span style={{ fontFamily:'DM Mono,monospace', fontSize:8, color:'rgba(242,240,235,0.2)' }}>{new Date(th.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</span>
                  </div>
                  <p style={{ fontSize:12, color:'rgba(242,240,235,0.3)', fontStyle:'italic', marginBottom:8, lineHeight:1.6 }}>"{th.user_text?.slice(0,90)}{th.user_text?.length>90?'...':''}"</p>
                  <p style={{ fontSize:12, color:'rgba(242,240,235,0.6)', lineHeight:1.65, fontWeight:300 }}>{th.reframe}</p>
                </div>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
